//! Fabric predicates, shared by dependency repair and Java selection.
//!
//! Fabric is not Cargo/npm semver: an empty prerelease is a valid lower
//! boundary, core versions can have any number of components, and ^0.x keeps
//! the entire zero major. Keep this independent of Maven/launcher versions.
//! Conformance fixtures are generated by the real Fabric Loader API.
//! Reference: https://github.com/FabricMC/fabric-loader/tree/0.20.1/src/main/java/net/fabricmc/loader/impl/util/version
use std::cmp::Ordering;

#[derive(Clone)]
struct Semantic<'a> {
    components: Vec<i32>,
    pre: Option<&'a str>,
    build: Option<&'a str>,
}
impl<'a> Semantic<'a> {
    fn parse(value: &'a str, wildcards: bool) -> Option<Self> {
        let (core, build) = value
            .split_once('+')
            .map_or((value, None), |(a, b)| (a, Some(b)));
        let (core, pre) = core
            .split_once('-')
            .map_or((core, None), |(a, b)| (a, Some(b)));
        if pre.is_some_and(|p| {
            !p.is_empty()
                && p.split('.').any(|s| {
                    s.is_empty() || !s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-')
                })
        }) {
            return None;
        }
        let mut components = Vec::new();
        let mut wildcard = false;
        for part in core.split('.') {
            if wildcards && matches!(part, "x" | "X" | "*") {
                if pre.is_some() {
                    return None;
                }
                if !wildcard || components[0] == -1 {
                    components.push(-1);
                }
                wildcard = true;
            } else {
                if wildcard || part.is_empty() || !part.bytes().all(|b| b.is_ascii_digit()) {
                    return None;
                }
                components.push(part.parse().ok()?);
            }
        }
        if components == [-1] {
            return None;
        }
        Some(Self {
            components,
            pre,
            build,
        })
    }
    fn component(&self, index: usize) -> i32 {
        self.components.get(index).copied().unwrap_or(0)
    }
    fn compare(&self, other: &Self) -> Ordering {
        for i in 0..self.components.len().max(other.components.len()) {
            let order = self.component(i).cmp(&other.component(i));
            if !order.is_eq() {
                return order;
            }
        }
        match (self.pre, other.pre) {
            (None, None) => Ordering::Equal,
            (None, Some(_)) => Ordering::Greater,
            (Some(_), None) => Ordering::Less,
            (Some(a), Some(b)) => {
                let mut left = a.split('.').filter(|s| !s.is_empty());
                let mut right = b.split('.').filter(|s| !s.is_empty());
                loop {
                    let order = match (left.next(), right.next()) {
                        (None, None) => return Ordering::Equal,
                        (None, Some(_)) => return Ordering::Less,
                        (Some(_), None) => return Ordering::Greater,
                        (Some(a), Some(b)) => {
                            let numeric = |s: &str| {
                                s == "0"
                                    || (!s.starts_with('0')
                                        && s.bytes().all(|b| b.is_ascii_digit()))
                            };
                            match (numeric(a), numeric(b)) {
                                (true, true) => a.len().cmp(&b.len()).then_with(|| a.cmp(b)),
                                (true, false) => Ordering::Less,
                                (false, true) => Ordering::Greater,
                                (false, false) => a.cmp(b),
                            }
                        }
                    };
                    if !order.is_eq() {
                        return order;
                    }
                }
            }
        }
    }
    fn friendly(&self) -> String {
        let mut value = self
            .components
            .iter()
            .map(i32::to_string)
            .collect::<Vec<_>>()
            .join(".");
        if let Some(pre) = self.pre {
            value.push('-');
            value.push_str(pre);
        }
        if let Some(build) = self.build {
            value.push('+');
            value.push_str(build);
        }
        value
    }
}

enum Version<'a> {
    Semantic(Semantic<'a>),
    String(&'a str),
}
impl<'a> Version<'a> {
    fn parse(value: &'a str, wildcards: bool) -> Option<Self> {
        if value.is_empty() {
            return None;
        }
        Some(Semantic::parse(value, wildcards).map_or(Self::String(value), Self::Semantic))
    }
    fn friendly(&self) -> std::borrow::Cow<'_, str> {
        match self {
            Self::String(s) => (*s).into(),
            Self::Semantic(s) => s.friendly().into(),
        }
    }
}

fn compare(actual: &Version<'_>, bound: &Version<'_>, op: &str) -> bool {
    let (Version::Semantic(a), Version::Semantic(b)) = (actual, bound) else {
        return !matches!(op, ">" | "<") && actual.friendly() == bound.friendly();
    };
    let order = a.compare(b);
    match op {
        "=" => order.is_eq(),
        ">=" => !order.is_lt(),
        "<=" => !order.is_gt(),
        ">" => order.is_gt(),
        "<" => order.is_lt(),
        "^" => !order.is_lt() && a.component(0) == b.component(0),
        "~" => {
            !order.is_lt() && a.component(0) == b.component(0) && a.component(1) == b.component(1)
        }
        _ => unreachable!(),
    }
}

fn predicate(range: &str, actual: &Version<'_>) -> Option<bool> {
    let mut result = true;
    // Deliberately match Java split(" ") + trim(), not split_whitespace().
    for term in range.split(' ').map(|s| s.trim_matches(|c| c <= '\u{20}')) {
        if term.is_empty() || term == "*" {
            continue;
        }
        let (mut op, value) = [">=", "<=", ">", "<", "=", "~", "^"]
            .into_iter()
            .find_map(|op| term.strip_prefix(op).map(|s| (op, s)))
            .unwrap_or(("=", term));
        let mut bound = Version::parse(value, true)?;
        match &mut bound {
            Version::Semantic(s) if s.components.last() == Some(&-1) => {
                if op != "=" || s.components[0] < 0 {
                    return None;
                }
                s.components.pop();
                s.pre = Some("");
                op = match s.components.len() {
                    1 => "^",
                    2 => "~",
                    _ => {
                        result &= compare(actual, &Version::Semantic(s.clone()), ">=");
                        let last = s.components.last_mut()?;
                        *last = last.wrapping_add(1);
                        s.build = None;
                        "<"
                    }
                };
            }
            Version::String(_) => {
                if matches!(op, ">" | "<") {
                    return None;
                }
                op = "=";
            }
            _ => {}
        }
        // Validate every term even after a mismatch; malformed isn't false.
        result &= compare(actual, &bound, op);
    }
    Some(result)
}

/// None means an invalid predicate/version, distinct from a known mismatch.
pub(crate) fn matches(range: &str, value: &str) -> Option<bool> {
    predicate(range, &Version::parse(value, false)?)
}

/// Fabric dependency arrays are OR; terms in each string are AND. Parse all
/// branches before accepting a match, as ModDependencyImpl does.
pub(crate) fn matches_json(range: &serde_json::Value, value: &str) -> Option<bool> {
    let actual = Version::parse(value, false)?;
    if let Some(items) = range.as_array() {
        let mut result = false;
        for item in items {
            result |= predicate(item.as_str()?, &actual)?;
        }
        Some(result)
    } else {
        predicate(range.as_str()?, &actual)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;
    #[test]
    fn reported_boundaries_and_array_validation() {
        for actual in ["1.20.5-", "1.20.5-alpha", "1.20.5", "1.21.1"] {
            assert_eq!(matches(">=1.20.5-", actual), Some(true));
        }
        assert_eq!(matches(">=1.20.5-", "1.20.4"), Some(false));
        assert_eq!(
            matches_json(&json!(["~1.21", "1.20.x"]), "1.21.1"),
            Some(true)
        );
        assert_eq!(matches_json(&json!(["*", ">invalid"]), "1.21.1"), None);
        assert_eq!(matches_json(&json!([]), "1.21.1"), Some(false));
        assert_eq!(matches_json(&json!([["*"]]), "1.21.1"), None);
    }
    #[test]
    fn official_loader_conformance() {
        let fixture: serde_json::Value = serde_json::from_str(include_str!(
            "../tests/fixtures/fabric-version-predicates.json"
        ))
        .unwrap();
        let versions = fixture["versions"].as_array().unwrap();
        for row in fixture["predicates"].as_array().unwrap() {
            let range = row[0].as_str().unwrap();
            let results = row[1].as_str().unwrap();
            assert_eq!(results.len(), versions.len());
            for (value, result) in versions.iter().zip(results.bytes()) {
                let value = value.as_str().unwrap();
                let expected = match result {
                    b'T' => Some(true),
                    b'F' => Some(false),
                    b'E' => None,
                    _ => panic!("bad fixture"),
                };
                assert_eq!(
                    matches(range, value),
                    expected,
                    "Fabric: {range:?} against {value:?}"
                );
            }
        }
    }
}
